export function precomposeMiddleware(middlewareChain: Middleware[]): Middleware {
  return (event, next) => {
    let index = 0;
    const composedNext = () => {
      if (index < middlewareChain.length) {
        const fn = middlewareChain[index++];
        return fn(event, composedNext);
      }
      return next();
    };
    return composedNext();
  };
}

